// lib
namespace Lib; public static class Marker { }

// app
using MessagePack;
namespace App;

// Source generation stays on, so the collector runs from the generator (reportDiagnostic is null).
// A is first and has a string key, so the type is in string-key mode (isIntKey = false).
// B is not first (searchFirst = false) and has an int key, so its stringKey is null.
// Old: nothing is reported for B and it carries on through the rest of the iteration.
// New: B hits `continue` and is left out of the generated formatter.
[MessagePackObject]
public partial class T
{
    [Key("a")] public int A { get; set; }
    [Key(1)] public int B { get; set; }
}

public static class Probe
{
    public static object Make() => new T { A = 1, B = 2 };
    public static string Show(object o) { var x = (T)o; return $"T {{ A = {x.A}, B = {x.B} }}"; }
}
